DROP TABLE IF EXISTS `admin_dashboard_snapshots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `admin_dashboard_snapshots` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `snapshot_date` date NOT NULL,
  `period_id` int(11) NOT NULL DEFAULT 0,
  `department` varchar(160) NOT NULL DEFAULT '',
  `program` varchar(160) NOT NULL DEFAULT '',
  `metrics_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`metrics_json`)),
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_admin_dashboard_snapshot` (`snapshot_date`,`period_id`,`department`,`program`)
) ENGINE=InnoDB AUTO_INCREMENT=93117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
