CREATE TABLE `backup_nero_rezzie_assignment_20260729` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `cycle_name` varchar(120) NOT NULL,
  `evaluator_user_id` int(11) NOT NULL,
  `evaluatee_faculty_id` int(11) NOT NULL,
  `evaluator_role` enum('vpaa','dean','program_head','teacher') NOT NULL,
  `assignment_type` enum('peer','program_head','dean','self') NOT NULL,
  `questionnaire_type` enum('admin','faculty') DEFAULT NULL,
  `status` enum('pending','in_progress','submitted','reassigned','cancelled','replaced','reopened','not_required') NOT NULL DEFAULT 'pending',
  `assigned_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `effective_from` datetime DEFAULT NULL,
  `effective_to` datetime DEFAULT NULL,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `replaced_by_assignment_id` int(11) DEFAULT NULL,
  `replacement_reason` varchar(500) DEFAULT NULL,
  `is_additional` tinyint(1) NOT NULL DEFAULT 0,
  `evaluator_name_snapshot` varchar(190) DEFAULT NULL,
