  KEY `idx_questionnaire_type` (`questionnaire_type`),
  KEY `idx_assignment_cycle_requirement` (`cycle_name`,`evaluatee_faculty_id`,`assignment_type`,`status`,`is_current`,`is_additional`),
  KEY `fk_assignment_replaced_by` (`replaced_by_assignment_id`)
