  `description` text NOT NULL,
  `message` text DEFAULT NULL,
  `link` varchar(500) DEFAULT NULL COMMENT 'Optional link to relevant page',
  `action_url` varchar(500) DEFAULT NULL,
  `module` varchar(80) DEFAULT NULL,
  `related_entity_type` varchar(50) DEFAULT NULL COMMENT 'e.g., evaluation, intervention, profile, period',
  `related_entity_id` int(11) DEFAULT NULL COMMENT 'ID of the related entity',
  `related_record_id` int(11) DEFAULT NULL,
  `is_read` tinyint(1) NOT NULL DEFAULT 0,
  `read_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_notifications_user_read` (`user_id`,`is_read`),
  KEY `idx_notifications_created` (`created_at`),
  CONSTRAINT `fk_notifications_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1569 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
