--
-- Table structure for table `peer_assignments`
--

DROP TABLE IF EXISTS `peer_assignments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `peer_assignments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `cycle_name` varchar(120) NOT NULL,
  `evaluator_user_id` int(11) NOT NULL,
  `evaluatee_faculty_id` int(11) NOT NULL,
  `evaluator_role` enum('vpaa','dean','program_head','teacher') NOT NULL,
  `assignment_type` enum('peer','program_head','dean','self') NOT NULL,
  `questionnaire_type` enum('admin','faculty') DEFAULT NULL,
  `status` enum('pending','in_progress','submitted','reassigned','cancelled','replaced','reopened','not_required') NOT NULL DEFAULT 'pending',
  `assigned_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `effective_from` datetime DEFAULT NULL,
  `effective_to` datetime DEFAULT NULL,
  `is_current` tinyint(1) NOT NULL DEFAULT 1,
  `replaced_by_assignment_id` int(11) DEFAULT NULL,
  `replacement_reason` varchar(500) DEFAULT NULL,
  `is_additional` tinyint(1) NOT NULL DEFAULT 0,
  `evaluator_name_snapshot` varchar(190) DEFAULT NULL,
  `evaluator_role_snapshot` varchar(40) DEFAULT NULL,
  `deadline` date DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `is_archived` tinyint(1) NOT NULL DEFAULT 0,
  `archived_at` datetime DEFAULT NULL,
  `archived_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_assignment` (`cycle_name`,`evaluator_user_id`,`evaluatee_faculty_id`,`assignment_type`),
  KEY `fk_assignment_evaluator` (`evaluator_user_id`),
  KEY `fk_assignment_faculty` (`evaluatee_faculty_id`),
  KEY `idx_questionnaire_type` (`questionnaire_type`),
  KEY `idx_assignment_cycle_requirement` (`cycle_name`,`evaluatee_faculty_id`,`assignment_type`,`status`,`is_current`,`is_additional`),
  KEY `fk_assignment_replaced_by` (`replaced_by_assignment_id`),
  CONSTRAINT `fk_assignment_evaluator` FOREIGN KEY (`evaluator_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_assignment_faculty` FOREIGN KEY (`evaluatee_faculty_id`) REFERENCES `faculty` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_assignment_replaced_by` FOREIGN KEY (`replaced_by_assignment_id`) REFERENCES `peer_assignments` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=394134 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
