INSERT INTO `pmas_self_evaluation_templates` VALUES (1,'form_b_faculty','PMAS Form B Self Evaluation for Faculty Members','faculty','{\"question1\":\"List down goals you have achieved and other significant accomplishments you have met during the appraisal period.\",\"question2\":\"List also goals that did not meet mutually agreed standards of performance and specify reasons why they were not met.\",\"question3\":\"What personal strengths do you have that contributed to your performance level during the appraisal period under review? How did they contribute to your performance level?\",\"question4\":\"How would you evaluate your overall performance considering performance outputs and work behaviors during this period in review?\",\"question5\":\"How can you further contribute your talents, knowledge, and skills to the organization to help improve its overall performance?\",\"strengthsQuestion\":\"What favorable qualities or attitudes other than those covered by the performance factors does the appraisee have which can help him\\/her excel in the performance of his\\/her job?\",\"improvementInstruction\":\"List areas in which the appraisee\'s qualities, attitudes, skills, and performance can be improved in relation to the present position. Itemize action plan to be undertaken in this regard.\"}',1,1,NULL,'2026-06-09 15:54:18','2026-06-09 15:54:18'),(2,'form_a_dean','PMAS Form A Self Evaluation for DEAN','dean','{\"question1\":\"List down goals you have achieved and other significant accomplishments you have met during the appraisal period.\",\"question2\":\"List also goals that did not meet mutually agreed standards of performance and specify reasons why they were not met.\",\"question3\":\"What personal strengths do you have that contributed to your performance level during the appraisal period under review? How did they contribute to your performance level?\",\"question4\":\"How would you evaluate your overall performance considering performance outputs and work behaviors during this period in review?\",\"question5\":\"How can you further contribute your talents, knowledge, and skills to the organization to help improve its overall performance?\",\"strengthsQuestion\":\"What favorable qualities or attitudes other than those covered by the performance factors does the appraisee have which can help him\\/her excel in the performance of his\\/her job?\",\"improvementInstruction\":\"List areas in which the appraisee\'s qualities, attitudes, skills, and performance can be improved in relation to the present position. Itemize action plan to be undertaken in this regard.\"}',1,1,4,'2026-06-09 15:56:47','2026-06-09 16:28:31'),(4,'form_a_vpaa','PMAS Form A Self Evaluation for VPAA','vpaa','{\"question1\":\"List down goals you have achieved and other significant accomplishments you have met during the appraisal period.\",\"question2\":\"List also goals that did not meet mutually agreed standards of performance and specify reasons why they were not met.\",\"question3\":\"What personal strengths do you have that contributed to your performance level during the appraisal period under review? How did they contribute to your performance level?\",\"question4\":\"How would you evaluate your overall performance considering performance outputs and work behaviors during this period in review?\",\"question5\":\"How can you further contribute your talents, knowledge, and skills to the organization to help improve its overall performance?\",\"strengthsQuestion\":\"What favorable qualities or attitudes other than those covered by the performance factors does the appraisee have which can help him\\/her excel in the performance of his\\/her job?\",\"improvementInstruction\":\"List areas in which the appraisee\'s qualities, attitudes, skills, and performance can be improved in relation to the present position. Itemize action plan to be undertaken in this regard.\"}',1,1,NULL,'2026-06-09 16:45:48','2026-06-09 16:45:48'),(5,'form_a_program_head','PMAS Form A Self Evaluation for PROGRAM HEAD','program_head','{\"question1\":\"List down goals you have achieved and other significant accomplishments you have met during the appraisal period.\",\"question2\":\"List also goals that did not meet mutually agreed standards of performance and specify reasons why they were not met.\",\"question3\":\"What personal strengths do you have that contributed to your performance level during the appraisal period under review? How did they contribute to your performance level?\",\"question4\":\"How would you evaluate your overall performance considering performance outputs and work behaviors during this period in review?\",\"question5\":\"How can you further contribute your talents, knowledge, and skills to the organization to help improve its overall performance?\",\"strengthsQuestion\":\"What favorable qualities or attitudes other than those covered by the performance factors does the appraisee have which can help him\\/her excel in the performance of his\\/her job?\",\"improvementInstruction\":\"List areas in which the appraisee\'s qualities, attitudes, skills, and performance can be improved in relation to the present position. Itemize action plan to be undertaken in this regard.\"}',1,1,NULL,'2026-06-10 17:03:03','2026-06-10 17:03:03');
