DROP TABLE IF EXISTS `pmas_self_evaluations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pmas_self_evaluations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `assignment_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `role` varchar(40) NOT NULL,
  `department` varchar(120) DEFAULT NULL,
  `evaluation_period` varchar(120) NOT NULL,
  `form_type` varchar(60) NOT NULL,
  `questionnaire_revision` int(11) DEFAULT NULL,
  `employee_info` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`employee_info`)),
  `answers_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`answers_json`)),
  `raw_payload_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`raw_payload_json`)),
  `form_payload_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`form_payload_json`)),
  `questionnaire_snapshot` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`questionnaire_snapshot`)),
  `performance_outputs_score` decimal(6,4) DEFAULT NULL,
  `performance_factors_score` decimal(6,4) DEFAULT NULL,
  `overall_rating` decimal(6,4) DEFAULT NULL,
  `performance_level` varchar(80) DEFAULT NULL,
  `status` enum('draft','submitted','reopened') NOT NULL DEFAULT 'draft',
  `submitted_at` datetime DEFAULT NULL,
  `reopened_at` datetime DEFAULT NULL,
  `reopened_by` int(11) DEFAULT NULL,
  `dean_review_status` enum('pending','approved','reopened','submitted_to_admin') NOT NULL DEFAULT 'pending',
  `dean_reviewed_by` int(11) DEFAULT NULL,
  `dean_reviewed_at` datetime DEFAULT NULL,
  `dean_review_notes` text DEFAULT NULL,
  `program_head_review_status` enum('pending','approved','reopened') NOT NULL DEFAULT 'pending',
  `program_head_reviewed_by` int(11) DEFAULT NULL,
  `program_head_reviewed_at` datetime DEFAULT NULL,
  `program_head_review_notes` text DEFAULT NULL,
  `vpaa_review_status` enum('pending','approved','reopened') NOT NULL DEFAULT 'pending',
  `vpaa_reviewed_by` int(11) DEFAULT NULL,
  `vpaa_reviewed_at` datetime DEFAULT NULL,
  `vpaa_review_notes` text DEFAULT NULL,
  `reopened_reason` text DEFAULT NULL,
  `revision_count` int(11) NOT NULL DEFAULT 0,
  `final_admin_submission_status` enum('not_ready','ready_for_admin','submitted_to_admin') NOT NULL DEFAULT 'not_ready',
  `admin_review_status` enum('none','pending','reviewed','returned_to_dean') NOT NULL DEFAULT 'none',
  `admin_reviewed_by` int(11) DEFAULT NULL,
  `admin_reviewed_at` datetime DEFAULT NULL,
  `admin_return_reason` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `assignment_id` (`assignment_id`),
  KEY `idx_self_eval_user_period` (`user_id`,`evaluation_period`),
  KEY `idx_self_eval_form_type` (`form_type`),
  CONSTRAINT `fk_self_eval_assignment` FOREIGN KEY (`assignment_id`) REFERENCES `peer_assignments` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_self_eval_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

